 if(!workspace)return <main className="boot"><div className="signin-language"><LanguageSwitch/></div><div className="brand-mark">S</div><h1>Sprint Overview</h1>{loading?<p>{t("Loading your shared plan…")}</p>:<><p role="alert">{message(error)}</p><Button onClick={load}>{t("Try again")}</Button><form action={logout}><button className="logout-button" type="submit">{t("Sign out")}</button></form></>}</main>;
 const {state,member}=workspace;
 const currentDate=today(state.settings.timezone),scopeEnd=dateAdd(scopeStart,13),visibleStart=dateAdd(scopeStart,-7),visibleEnd=dateAdd(scopeStart,20);
