 const r=page==='planning'?focusedReport:workspace.reports[sprint.id];const source=page==='planning'?state:sprintData(state,sprint);const editable=member.role!=='viewer';const canPlan=editable&&(page==='planning'||sprint.status!=='closed');const isAdmin=member.role==='admin';
 const days=dates(visibleStart,visibleEnd),cw=zoom==='day'?78:Math.max(26,(boardWidth-personWidth)/28);
