 const filtered=chartPeople.filter(p=>(!query||`${p.employee.name} ${p.employee.skills.join(' ')}`.toLowerCase().includes(query.toLowerCase()))&&(!discipline||p.employee.discipline===discipline)&&(!teamFilter||p.teams.includes(teamFilter)));
 function chooseScope(date:string){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date+'T12:00:00Z')))return;const start=mondayOf(date);setScopeStart(start);const target=sprintOnDate(state,start);if(target)setSprintId(target.id);}
 function chooseSprint(id:string){setSprintId(id);if(page==='planning'){const target=state.sprints.find(s=>s.id===id);if(target)chooseScope(target.start);}}
 const orderedSprints=[...state.sprints].sort((a,b)=>a.start.localeCompare(b.start));const sprintIndex=orderedSprints.findIndex(s=>s.id===sprint.id);
 const nextSprint=orderedSprints.find(s=>s.start>currentDate&&s.status!=='closed');
