 const conflicts=r.people.flatMap(p=>p.cells.filter(c=>c.conflicts.length).map(c=>({p,c})));const disciplines=[...DISCIPLINES];const displayTeams=source.teams.filter(team=>!team.archived||(page==='planning'?chartPeople:r.people).some(p=>p.teams.includes(team.id)));
