 const formTitle:Record<string,string>={allocation:draft.id?t("Edit allocation"):t("Add allocation"),employee:draft.id?t("Edit employee"):t("Add employee"),absence:t("Record absence"),override:t("Daily availability"),award:t("Award bonus points"),sprint:draft.copyFrom?t("Copy into a new sprint"):t("Create sprint"),team:draft.id?t("Edit team"):t("Add team"),project:draft.id?t("Edit project"):t("Add project"),settings:t("Planning preferences"),holiday:t("Add holiday"),member:t("Manager access"),day:t("Daily plan"),confirm:t(modal?.title??'Confirm change')};
