 const summaryCards=<div className="summary-grid"><Summary icon={Users} label={t("Available capacity")} value={`${hours(r.capacity)} h`} sub={page==='planning'?t('{count} people · selected weeks',{count:r.people.length}):t('{count} people · this sprint',{count:r.people.length})} tone="blue"/><Summary icon={Layers3} label={t("Allocated")} value={`${hours(r.allocated)} h`} sub={t('{percent}% of available capacity',{percent:r.capacity?Math.round(r.allocated/r.capacity*100):0})} tone="purple"/><Summary icon={Clock3} label={t("Remaining")} value={`${hours(r.remaining)} h`} sub={t("Across all teams")} tone="teal"/><Summary icon={AlertTriangle} label={t("Conflict days")} value={String(r.conflictDays)} sub={r.conflictDays?t("Need planning attention"):t("No booking conflicts")} tone={r.conflictDays?'red':'teal'}/></div>;
 function alerts(limit=4){return <section className="panel alert-panel"><div className="panel-head"><h2>{t("Planning alerts")} <span className="count">{conflicts.length}</span></h2><span className="muted">{t("Across all teams")}</span></div>{!conflicts.length?<div className="all-clear"><CheckCircle2 size={20}/><div><strong>{t("The plan is clear")}</strong><p>{t("Daily workload fits available capacity.")}</p></div></div>:conflicts.slice(0,limit).map(({p,c})=><button className="alert-row" key={p.employee.id+c.date} onClick={()=>open('day',{employeeId:p.employee.id,date:c.date})}><span className="alert-icon"><AlertTriangle size={18}/></span><span><strong>{p.employee.name.split(' ')[0]} <b>·</b> {dateLabel(c.date,{weekday:'short',day:'numeric'})}</strong><small>{c.conflicts.map(message).join(' · ')}</small></span><ArrowUpRight size={17}/></button>)}{conflicts.length>limit&&<Button variant="ghost" size="sm" onClick={()=>open('alerts')}>{t('View {count} conflict days',{count:conflicts.length})} <ArrowRight size={14}/></Button>}</section>;}
