 {modal?.kind==='employee'&&<><div className="form-grid"><Field label={t("Full name")}><TextInput value={draft.name} onChange={(v:string)=>set('name',v)}/></Field><Field label={t("Discipline")}><Select value={draft.discipline} onChange={(v:string)=>set('discipline',v)}>{DISCIPLINES.map(d=><option key={d} value={d}>{t(d)}</option>)}</Select></Field></div><Field label={t("Skills")} hint={t("Separate skills with commas.")}><TextInput value={draft.skills} onChange={(v:string)=>set('skills',v)} placeholder={t("Blender, Modeling, Texturing")}/></Field><div className="form-grid"><Field label={t("Employment start (optional)")}><TextInput type="date" value={draft.employmentStart} onChange={(v:string)=>set('employmentStart',v)}/></Field><Field label={t("Employment end (optional)")}><TextInput type="date" value={draft.employmentEnd} onChange={(v:string)=>set('employmentEnd',v)}/></Field></div><Field label={t("Schedule effective from")}><TextInput type="date" value={draft.effectiveFrom} onChange={(v:string)=>set('effectiveFrom',v)}/></Field><div className="schedule-editor"><div className="schedule-head"><strong>{t('Recurring daily capacity')}</strong><small>{t('Hours available on each weekday')}</small></div><div className="schedule-days" tabIndex={0} role="region" aria-label={t('Recurring daily capacity')}>{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((day,index)=><div className="schedule-day" key={day}><label>{t(day)}</label><TextInput type="number" aria-label={t('Daily capacity for {day}',{day:t(day)})} min="0" max="24" step="0.25" value={(draft.dailyMinutes?.[index]??0)/60} onChange={(value:string)=>set('dailyMinutes',{...draft.dailyMinutes,[index]:Math.round(Number(value)*60)})}/><small>{t('hours')}</small></div>)}</div></div></>}
 {modal?.kind==='absence'&&<><Field label={t("Employee")}><Select value={draft.employeeId} onChange={(v:string)=>set('employeeId',v)}>{employeeOptions}</Select></Field><div className="form-grid"><Field label={t("From")}><TextInput type="date" value={draft.start} onChange={(v:string)=>set('start',v)}/></Field><Field label={t("Through")}><TextInput type="date" value={draft.end} onChange={(v:string)=>set('end',v)}/></Field></div><Field label={t("Category")}><Select value={draft.category} onChange={(v:string)=>set('category',v)}><option value="Leave">{t("Leave")}</option><option value="Unavailable">{t("Unavailable")}</option><option value="Personal time">{t("Personal time")}</option></Select></Field><label className="check-label"><input type="checkbox" checked={draft.fullDay} onChange={e=>set('fullDay',e.target.checked)}/>  {t("Full day")}</label>{!draft.fullDay&&dailyHoursField}<p className="form-note">{t("Availability is updated immediately. Existing assignments stay in the plan and are flagged if they conflict.")}</p></>}
