 {modal?.kind==='award'&&<><Field label={t("Recipient")}><Select value={draft.employeeId} onChange={(v:string)=>set('employeeId',v)}>{employeeOptions}</Select></Field><div className="form-grid"><Field label={t("Points")} hint={t('Each award adds exactly one point.')}><div className="input fixed-point">{t('1 point')}</div></Field><Field label={t("Category")}><Select value={draft.category} onChange={(v:string)=>set('category',v)}>{state.settings.awardCategories.map(c=><option key={c} value={c}>{t(c)}</option>)}</Select></Field></div><Field label={t("Basis")}><Select value={draft.basis} onChange={(v:string)=>set('basis',v)}><option value="qualitative">{t("Qualitative")}</option><option value="quantitative">{t("Quantitative")}</option></Select></Field><Field label={t("Why are they receiving these points?")}><textarea className="input" rows={3} value={draft.reason} onChange={e=>set('reason',e.target.value)} placeholder={t("Describe the contribution and its impact.")}/></Field>{draft.basis==='quantitative'&&<><Field label={t("Metric")}><TextInput value={draft.metric} onChange={(v:string)=>set('metric',v)} placeholder={t("e.g. Build preparation time")}/></Field><div className="form-grid three"><Field label={t("Before")}><TextInput value={draft.before} onChange={(v:string)=>set('before',v)}/></Field><Field label={t("After")}><TextInput value={draft.after} onChange={(v:string)=>set('after',v)}/></Field><Field label={t("Unit")}><TextInput value={draft.unit} onChange={(v:string)=>set('unit',v)}/></Field></div></>}<Field label={t("Evidence URL (optional)")}><TextInput value={draft.evidence} onChange={(v:string)=>set('evidence',v)} placeholder="https://…"/></Field><div className="form-grid"><Field label={t("Award date")}><TextInput type="date" value={draft.date} onChange={(v:string)=>set('date',v)}/></Field><Field label={t("Related sprint")}><Select value={draft.sprintId} onChange={(v:string)=>set('sprintId',v)}><option value="">{t("No sprint")}</option>{state.sprints.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</Select></Field></div></>}
 {modal?.kind==='sprint'&&<><Field label={t("Name")}><TextInput value={draft.name} onChange={(v:string)=>set('name',v)}/></Field><Field label={t("Start date")}><TextInput type="date" value={draft.start} onChange={(v:string)=>set('start',v)}/></Field><Field label={t("Copy allocations from")}><Select value={draft.copyFrom} onChange={(v:string)=>set('copyFrom',v)}><option value="">{t("Start with an empty plan")}</option>{state.sprints.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</Select></Field><p className="form-note">{t("Sprints cover 14 calendar days. Copied assignments are shifted to the new dates; availability is recalculated, and conflicts remain visible in the draft.")}</p></>}
