 {modal?.kind==='settings'&&<><Field label={t("Organization timezone")}><TextInput value={draft.timezone} onChange={(v:string)=>set('timezone',v)}/></Field><Field label={t("Planning buffer (%)")}><TextInput type="number" min="0" max="50" value={draft.buffer} onChange={(v:string)=>set('buffer',Number(v))}/></Field><Field label={t("Award categories")} hint={t("One category per line.")}><textarea className="input" rows={6} value={draft.awardCategories} onChange={e=>set('awardCategories',e.target.value)}/></Field></>}
