 {modal?.kind==='day'&&<DailyDetail person={(page==='planning'?chartPeople:r.people).find(p=>p.employee.id===modal.employeeId)} date={modal.date} state={source} canEdit={editable&&sprintOnDate(state,modal.date)?.status!=='closed'} onAllocation={a=>open(canEditAllocation(a)?'allocation':'allocationDetail',{allocation:a})} onAdd={()=>open('allocation',{employeeId:modal.employeeId,date:modal.date})} onAvailability={()=>open('override',{employeeId:modal.employeeId,date:modal.date})} onAbsence={()=>open('absence',{employeeId:modal.employeeId,date:modal.date})}/>}
 {modal?.kind==='person'&&(()=>{const e=state.employees.find(e=>e.id===modal.employeeId)!;const p=r.people.find(p=>p.employee.id===e.id);return <><div className="person-profile"><Avatar employee={e} size={52}/><div><h2>{e.name}</h2><p>{t(e.discipline)}</p><div className="skill-list">{e.skills.map(s=><span key={s}>{s}</span>)}</div></div></div><div className="profile-stats"><span>{t("Available")}<strong>{hours(p?.capacity??0)} h</strong></span><span>{t("Allocated")}<strong>{hours(p?.allocated??0)} h</strong></span><span>{t("Remaining")}<strong>{hours(p?.remaining??0)} h</strong></span></div><div className="profile-actions">{editable&&<><Button variant="outline" onClick={()=>open('employee',{employee:e})}><Pencil size={15}/>  {t("Edit profile & schedule")}</Button><Button variant="outline" onClick={()=>open('absence',{employeeId:e.id})}><CalendarDays size={15}/>  {t("Record absence")}</Button><Button variant="outline" onClick={()=>open('award',{employeeId:e.id})}><AwardIcon size={15}/>  {t("Award points")}</Button></>}</div><h3 className="section-label">{t("Daily capacity ·")} {page==='planning'?`${dateLabel(scopeStart)} – ${dateLabel(scopeEnd)}`:sprint.name}</h3><div className="profile-days">{p?.cells.map(c=><button key={c.date} onClick={()=>open('day',{employeeId:e.id,date:c.date})}><span>{dateLabel(c.date,{weekday:'short',day:'numeric'})}</span><strong>{hours(c.allocated)} / {hours(c.capacity)} h</strong>{c.conflicts.length?<AlertTriangle size={15} className="red-text"/>:c.leave?<Pill>{t("Leave")}</Pill>:null}</button>)}</div><h3 className="section-label">{t("Recorded absences")}</h3>{state.absences.filter(a=>a.employeeId===e.id).map(a=><div className="setting-row" key={a.id}><div><strong>{a.category}</strong><small>{dateLabel(a.start)} – {dateLabel(a.end)} · {a.fullDay||a.windows.some(w=>w[0]===0&&w[1]===1440)?t('Full day'):`${hours(a.minutesPerDay??duration(a.windows))} ${t('h/day')}`}</small></div>{editable&&<Button variant="ghost" size="icon-sm" aria-label={t("Remove absence")} onClick={()=>confirm('absence.remove',{id:a.id},'Remove absence','Availability will be recalculated. Existing allocations remain.') }><Trash2 size={15}/></Button>}</div>)}{editable&&<Button variant="ghost" className="archive-button" onClick={()=>confirm('employee.archive',{id:e.id,archived:!e.archived},e.archived?'Restore employee':'Archive employee','Historical records and existing allocations are preserved.')}>{e.archived?t("Restore employee"):t("Archive employee")}</Button>}</>;})()}
 {modal?.kind==='allocationDetail'&&<div className="allocation-detail"><h2>{modal.allocation.label}</h2><p>{state.employees.find(e=>e.id===modal.allocation.employeeId)?.name}</p><Pill>{source.teams.find(team=>team.id===modal.allocation.teamId)?.name??'Internal'}</Pill><p>{dateLabel(modal.allocation.start)} – {dateLabel(modal.allocation.end)}</p><p>{hours(allocationMinutes(modal.allocation))} {t('h/day')}</p>{modal.allocation.issueUrl&&<a target="_blank" rel="noreferrer" href={modal.allocation.issueUrl}>{t("Open reference")} <ArrowUpRight size={14}/></a>}</div>}
 {modal?.kind==='alerts'&&conflicts.map(({p,c})=><button className="alert-row" key={p.employee.id+c.date} onClick={()=>open('day',{employeeId:p.employee.id,date:c.date})}><AlertTriangle size={18}/><span><strong>{p.employee.name} · {dateLabel(c.date)}</strong><small>{c.conflicts.map(message).join(' · ')}</small></span><ArrowUpRight size={15}/></button>)}
