function Summary({icon:Icon,label,value,sub,tone}:any){const {t,message,locale,hours,dateLabel}=useI18n();return <div className="summary-card"><div><span className="metric-label">{label}</span><strong>{value}</strong><small>{sub}</small></div><span className={'metric-icon '+tone}><Icon size={20}/></span></div>;}
function AuditList({events}:{events:State['audit']}){const {t,message,locale,hours,dateLabel}=useI18n();return <div className="audit-list">{!events.length?<p className="muted padded">{t("Changes will appear here as the team updates the plan.")}</p>:events.map(a=><div key={a.id}><span className="audit-dot"/><div><strong>{a.action==='workspace.configure'?t('Company people and teams configured'):a.detail}</strong><p>{t(a.action)} · {a.actor}{a.reason&&` · ${a.reason}`}</p></div><time>{new Date(a.at).toLocaleString(locale,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time></div>)}</div>;}
function AllocationPreview({state,draft}:any){const {t,hours}=useI18n();try{if(!draft.start||!draft.end||draft.end<draft.start||!draft.hoursPerDay)return null;const list=dates(draft.start,draft.end).filter(date=>draft.weekdays.includes(dayOf(date)));const missing=list.filter(date=>!sprintOnDate(state,date));const minuteQuantity=Math.round(Number(draft.hoursPerDay)*60);const next={...state,sprints:state.sprints.map((s:any)=>({...s,status:s.status==='closed'?'closed':'draft'})),allocations:[...state.allocations.filter((a:any)=>a.id!==draft.id),...list.flatMap(date=>{const target=sprintOnDate(state,date);return target?[{...draft,id:'preview-'+date,sprintId:target.id,start:date,end:date,minutesPerDay:minuteQuantity,windows:[]}]:[];})]};const person=rangeReport(next,draft.start,draft.end).people.find(p=>p.employee.id===draft.employeeId);const conflictDays=person?.cells.filter(c=>c.conflicts.length).length??0;return <div className="allocation-preview"><strong>{t('{days} days · {hours} h planned',{days:list.length,hours:hours(list.length*minuteQuantity)})}</strong>{missing.length?<p className="red-text"><AlertTriangle size={14}/>{t('Create a sprint for every selected working day before saving')}</p>:conflictDays?<p className="red-text"><AlertTriangle size={14}/>{t('{days} days have conflicts.',{days:conflictDays})}</p>:<p><CheckCircle2 size={14}/>{t('Fits daily capacity across all teams.')}</p>}</div>;}catch{return null;}}
function DailyDetail({person,date,state,canEdit,onAllocation,onAdd,onAvailability,onAbsence}:{person?:PersonReport;date:string;state:State;canEdit:boolean;onAllocation:(a:Allocation)=>void;onAdd:()=>void;onAvailability:()=>void;onAbsence:()=>void}){const {t,message,hours}=useI18n();if(!person)return null;const cell=person.cells.find(c=>c.date===date);if(!cell)return null;const sprint=sprintOnDate(state,date);return <><div className="profile-stats"><span>{t('Available')}<strong>{hours(cell.capacity)} h</strong></span><span>{t('Allocated')}<strong>{hours(cell.allocated)} h</strong></span><span>{t('Remaining')}<strong>{hours(cell.capacity-cell.allocated)} h</strong></span></div>{cell.conflicts.length>0&&<div className="error-banner">{cell.conflicts.map(message).join(' · ')}</div>}<div className="daily-sprint"><CalendarRange size={16}/>{sprint?.name??t('No sprint')}{sprint&&<Pill>{t(sprint.status[0].toUpperCase()+sprint.status.slice(1))}</Pill>}</div><h3 className="section-label">{t('Work planned for this day')}</h3>{cell.allocations.map(a=><button className="daily-allocation" key={a.id} onClick={()=>onAllocation(a)}><span><strong>{a.label}</strong><small>{state.teams.find(team=>team.id===a.teamId)?.name??t('Internal')}</small></span><Pill>{hours(allocationMinutes(a))} h</Pill><ArrowUpRight size={15}/></button>)}{!cell.allocations.length&&<p className="muted">{t('No assignments on this day.')}</p>}{canEdit&&<div className="profile-actions"><Button onClick={onAdd} disabled={!sprint}><Plus size={15}/>{t('Add allocation')}</Button><Button variant="outline" onClick={onAvailability}>{t('Change availability')}</Button><Button variant="outline" onClick={onAbsence}>{t('Record absence')}</Button></div>}</>;}
